1	// SPDX-FileCopyrightText: Copyright (c) 2024-2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
2	// SPDX-License-Identifier: Apache-2.0
3	
4	//! Single-threaded compressed radix tree for KV cache routing.
5	
6	use std::{cell::RefCell, collections::VecDeque, rc::Rc};
7	
8	use rustc_hash::{FxBuildHasher, FxHashMap, FxHashSet};
9	
10	use super::compressed_radix::{NodeState, append_dump_events};
11	use super::{EventWarningKind, MatchDetails, PreBoundEventCounters};
12	use crate::protocols::*;
13	
14	pub(crate) type SharedRadixBlock = Rc<RefCell<RadixBlock>>;
15	type WorkerLookup = FxHashMap<ExternalSequenceBlockHash, SharedRadixBlock>;
16	
17	#[derive(Debug)]
18	pub(crate) struct RadixBlock {
19	    state: NodeState,
20	    children: FxHashMap<LocalBlockHash, SharedRadixBlock>,
21	    /// Once a node has children it is never eligible for leaf extension again.
22	    internal: bool,
23	}
24	
25	impl RadixBlock {
26	    fn root() -> Self {
27	        Self {
28	            state: NodeState::empty(),
29	            children: FxHashMap::default(),
30	            internal: true,
31	        }
32	    }
33	
34	    fn for_blocks(blocks: &[KvCacheStoredBlockData], worker: WorkerWithDpRank) -> Self {
35	        Self {
36	            state: NodeState::for_blocks(blocks, worker),
37	            children: FxHashMap::default(),
38	            internal: false,
39	        }
40	    }
41	
42	    fn clear_children_if_unreachable(&mut self) {
43	        if self.state.full_edge_workers.is_empty() {
44	            self.children.clear();
45	        }
46	    }
47	}
48	
49	pub struct RadixTree {
50	    root: SharedRadixBlock,
51	    lookup: FxHashMap<WorkerWithDpRank, WorkerLookup>,
52	}
53	
54	impl Default for RadixTree {
55	    fn default() -> Self {
56	        Self::new()
57	    }
58	}
59	
60	impl Drop for RadixTree {
61	    fn drop(&mut self) {
62	        let mut stack = self
63	            .root
64	            .borrow_mut()
65	            .children
66	            .drain()
67	            .map(|(_, child)| child)
68	            .collect::<Vec<_>>();
69	        for (_, worker_lookup) in self.lookup.drain() {
70	            stack.extend(worker_lookup.into_values());
71	        }
72	
73	        while let Some(block) = stack.pop() {
74	            if let Ok(cell) = Rc::try_unwrap(block) {
75	                stack.extend(cell.into_inner().children.into_values());
76	            }
77	        }
78	    }
79	}
80	
81	impl RadixTree {
82	    pub fn new() -> Self {
83	        Self {
84	            root: Rc::new(RefCell::new(RadixBlock::root())),
85	            lookup: FxHashMap::default(),
86	        }
87	    }
88	
89	    pub fn find_match_details(
90	        &self,
91	        sequence: Vec<LocalBlockHash>,
92	        early_exit: bool,
93	    ) -> MatchDetails {
94	        self.find_match_details_with_options(sequence, early_exit, false)
95	    }
96	
97	    pub fn find_match_details_with_options(
98	        &self,
99	        sequence: Vec<LocalBlockHash>,
100	        early_exit: bool,
101	        retain_router_hint_chain: bool,
102	    ) -> MatchDetails {
103	        let mut details = MatchDetails::new();
104	        if sequence.is_empty() {
105	            return details;
106	        }
107	
108	        let mut next = self.root.borrow().children.get(&sequence[0]).cloned();
109	        let mut active = FxHashSet::default();
110	        let mut matched_depth = 0usize;
111	        let mut seq_pos = 0usize;
112	        let mut first_node = true;
113	        let mut last_matched_hash = None;
114	        let mut router_hint_root_chain =
115	            retain_router_hint_chain.then(|| Vec::with_capacity(sequence.len()));
116	
117	        while seq_pos < sequence.len() {
118	            let Some(node) = next.take() else {
119	                break;
120	            };
121	            let node = node.borrow();
122	            let walk_len = node.state.edge.len().min(sequence.len() - seq_pos);
123	            let edge_match_len = node
124	                .state
125	                .edge
126	                .iter()
127	                .take(walk_len)
128	                .zip(&sequence[seq_pos..])
129	                .take_while(|((local_hash, _), query_hash)| local_hash == *query_hash)
130	                .count();
131	
132	            if edge_match_len == 0 {
133	                break;
134	            }
135	
136	            if let Some(block_hashes) = router_hint_root_chain.as_mut() {
137	                block_hashes.extend(
138	                    node.state
139	                        .edge
140	                        .iter()
141	                        .take(edge_match_len)
142	                        .map(|(_, block_hash)| *block_hash),
143	                );
144	            }
145	
146	            if first_node {
147	                active.clone_from(&node.state.full_edge_workers);
148	                for (&worker, &cutoff) in &node.state.worker_cutoffs {
149	                    let contribution = cutoff.min(edge_match_len);
150	                    if contribution == 0 {
151	                        continue;
152	                    }
153	                    details
154	                        .overlap_scores
155	                        .scores
156	                        .insert(worker, contribution as u32);
157	                    details
158	                        .last_matched_hashes
159	                        .insert(worker, node.state.edge[contribution - 1].1);
160	                }
161	                first_node = false;
162	            } else {
163	                active.retain(|worker| {
164	                    if node.state.full_edge_workers.contains(worker) {
165	                        return true;
166	                    }
167	
168	                    if let Some(&cutoff) = node.state.worker_cutoffs.get(worker) {
169	                        let contribution = cutoff.min(edge_match_len);
170	                        details
171	                            .overlap_scores
172	                            .scores
173	                            .insert(*worker, (matched_depth + contribution) as u32);
174	                        let hash = if contribution > 0 {
175	                            node.state.edge[contribution - 1].1
176	                        } else {
177	                            last_matched_hash.expect("non-root match must have a prior hash")
178	                        };
179	                        details.last_matched_hashes.insert(*worker, hash);
180	                    } else {
181	                        details
182	                            .overlap_scores
183	                            .scores
184	                            .insert(*worker, matched_depth as u32);
185	                        if let Some(hash) = last_matched_hash {
186	                            details.last_matched_hashes.insert(*worker, hash);
187	                        }
188	                    }
189	                    false
190	                });
191	            }
192	
193	            matched_depth += edge_match_len;
194	            last_matched_hash = Some(node.state.edge[edge_match_len - 1].1);
195	
196	            if active.is_empty()
197	                || edge_match_len < node.state.edge.len()
198	                || matched_depth == sequence.len()
199	                || (early_exit && active.len() == 1)
200	            {
201	                break;
202	            }
203	
204	            seq_pos += edge_match_len;
205	            next = node.children.get(&sequence[seq_pos]).cloned();
206	        }
207	
208	        for worker in active {
209	            details
210	                .overlap_scores
211	                .scores
212	                .insert(worker, matched_depth as u32);
213	            if let Some(hash) = last_matched_hash {
214	                details.last_matched_hashes.insert(worker, hash);
215	            }
216	        }
217	
218	        if let Some(block_hashes) = router_hint_root_chain {
219	            details.retain_router_hint_root_candidates(block_hashes);
220	        }
221	
222	        details
223	    }
224	
225	    pub fn find_matches(&self, sequence: Vec<LocalBlockHash>, early_exit: bool) -> OverlapScores {
226	        self.find_match_details(sequence, early_exit).overlap_scores
227	    }
228	
229	    pub fn apply_event(&mut self, event: RouterEvent) -> Result<(), KvCacheEventError> {
230	        self.apply_event_with_counters(event, None)
231	    }
232	
233	    pub(crate) fn apply_event_with_counters(
234	        &mut self,
235	        event: RouterEvent,
236	        counters: Option<&PreBoundEventCounters>,
237	    ) -> Result<(), KvCacheEventError> {
238	        let worker = WorkerWithDpRank::new(event.worker_id, event.event.dp_rank);
239	        let event_id = event.event.event_id;
240	        self.lookup.entry(worker).or_default();
241	
242	        match event.event.data {
243	            KvCacheEventData::Stored(store) => self.apply_stored(worker, store, event_id, counters),
244	            KvCacheEventData::Removed(remove) => self.apply_removed(worker, remove, event_id),
245	            KvCacheEventData::Cleared => {
246	                self.remove_worker_dp_rank(worker.worker_id, worker.dp_rank);
247	                Ok(())
248	            }
249	        }
250	    }
251	
252	    fn apply_stored(
253	        &mut self,
254	        worker: WorkerWithDpRank,
255	        store: KvCacheStoreData,
256	        event_id: u64,
257	        counters: Option<&PreBoundEventCounters>,
258	    ) -> Result<(), KvCacheEventError> {
259	        // NOTE: This is a single-threaded indexer defense, not a cross-indexer validation
260	        // contract. Publishers must not emit self-referencing stores; concurrent consumer
261	        // indexers intentionally trust that guarantee to avoid this O(blocks) hot-path scan.
262	        // Do not copy this validation into CRTC solely for implementation parity.
263	        if let Some(parent_hash) = store.parent_hash
264	            && store
265	                .blocks
266	                .iter()
267	                .any(|block| block.block_hash == parent_hash)
268	        {
269	            tracing::warn!(
270	                worker_id = worker.worker_id,
271	                dp_rank = worker.dp_rank,
272	                event_id,
273	                ?parent_hash,
274	                "Detected self-referencing store event"
275	            );
276	            return Err(KvCacheEventError::InvalidBlockSequence);
277	        }
278	
279	        let mut duplicate_store = !store.blocks.is_empty();
280	        let mut parent = match store.parent_hash {
281	            Some(parent_hash) => {
282	                let Some(node) = self.lookup[&worker].get(&parent_hash).cloned() else {
283	                    self.log_missing_parent(worker, event_id, &store);
284	                    return Err(KvCacheEventError::ParentBlockNotFound);
285	                };
286	                let parent_pos = {
287	                    let node_ref = node.borrow();
288	                    let Some(&pos) = node_ref.state.edge_index.get(&parent_hash) else {
289	                        self.log_missing_parent(worker, event_id, &store);
290	                        return Err(KvCacheEventError::ParentBlockNotFound);
291	                    };
292	                    if !node_ref.state.covers_pos(worker, pos) {
293	                        self.lookup.get_mut(&worker).unwrap().remove(&parent_hash);
294	                        self.log_missing_parent(worker, event_id, &store);
295	                        return Err(KvCacheEventError::ParentBlockNotFound);
296	                    }
297	                    pos
298	                };
299	
300	                if let Some(done_duplicate) =
301	                    self.try_reuse_parent_edge(worker, &node, parent_pos, &store.blocks)
302	                {
303	                    duplicate_store &= done_duplicate;
304	                    if duplicate_store && let Some(counters) = counters {
305	                        counters.inc_warning(EventWarningKind::DuplicateStore);
306	                    }
307	                    return Ok(());
308	                }
309	
310	                if !node.borrow().state.tail_hash_is(parent_hash) {
311	                    self.split_node(&node, parent_pos + 1);
312	                }
313	                node
314	            }
315	            None => self.root.clone(),
316	        };
317	
318	        let mut remaining = store.blocks.as_slice();
319	        while !remaining.is_empty() {
320	            let first_local = remaining[0].tokens_hash;
321	            let child = parent.borrow().children.get(&first_local).cloned();
322	
323	            let Some(child) = child else {
324	                let can_extend = {
325	                    let parent_ref = parent.borrow();
326	                    !parent_ref.state.edge.is_empty()
327	                        && !parent_ref.internal
328	                        && parent_ref
329	                            .state
330	                            .covers_pos(worker, parent_ref.state.edge.len() - 1)
331	                };
332	                if can_extend {
333	                    parent
334	                        .borrow_mut()
335	                        .state
336	                        .append_blocks_to_leaf(worker, remaining);
337	                    self.update_lookup_for_blocks(worker, remaining, &parent);
338	                    duplicate_store = false;
339	                    break;
340	                }
341	
342	                let child = Rc::new(RefCell::new(RadixBlock::for_blocks(remaining, worker)));
343	                {
344	                    let mut parent_ref = parent.borrow_mut();
345	                    parent_ref.internal = true;
346	                    parent_ref.children.insert(first_local, child.clone());
347	                }
348	                self.update_lookup_for_blocks(worker, remaining, &child);
349	                duplicate_store = false;
350	                break;
351	            };
352	
353	            let (edge_len, match_len, mismatch) = {
354	                let child_ref = child.borrow();
355	                let edge_len = child_ref.state.edge.len();
356	                let mut mismatch = None;
357	                let match_len = child_ref
358	                    .state
359	                    .edge
360	                    .iter()
361	                    .zip(remaining)
362	                    .take_while(|((local_hash, existing_hash), block)| {
363	                        if local_hash != &block.tokens_hash {
364	                            return false;
365	                        }
366	                        if existing_hash != &block.block_hash && mismatch.is_none() {
367	                            mismatch = Some((block.block_hash, *existing_hash));
368	                        }
369	                        true
370	                    })
371	                    .count();
372	                (edge_len, match_len, mismatch)
373	            };
374	
375	            if let Some((expected, actual)) = mismatch {
376	                duplicate_store = false;
377	                tracing::warn!(
378	                    ?expected,
379	                    ?actual,
380	                    "block_hash mismatch: sequence hashes should be uniform across workers"
381	                );
382	            }
383	
384	            if match_len < edge_len {
385	                if match_len == remaining.len() {
386	                    let changed = child
387	                        .borrow_mut()
388	                        .state
389	                        .cover_prefix_for_worker(worker, match_len);
390	                    duplicate_store &= !changed;
391	                    duplicate_store &= !self.update_lookup_for_blocks(worker, remaining, &child);
392	                    break;
393	                }
394	
395	                self.split_node(&child, match_len);
396	                child.borrow_mut().state.promote_to_full(worker);
397	                self.update_lookup_for_blocks(worker, &remaining[..match_len], &child);
398	
399	                let tail = &remaining[match_len..];
400	                let tail_node = Rc::new(RefCell::new(RadixBlock::for_blocks(tail, worker)));
401	                {
402	                    let mut child_ref = child.borrow_mut();
403	                    child_ref.internal = true;
404	                    child_ref
405	                        .children
406	                        .insert(tail[0].tokens_hash, tail_node.clone());
407	                }
408	                self.update_lookup_for_blocks(worker, tail, &tail_node);
409	                duplicate_store = false;
410	                break;
411	            }
412	
413	            if child.borrow_mut().state.promote_to_full(worker) {
414	                duplicate_store = false;
415	            }
416	            if self.update_lookup_for_blocks(worker, &remaining[..edge_len], &child) {
417	                duplicate_store = false;
418	            }
419	            remaining = &remaining[edge_len..];
420	            parent = child;
421	        }
422	
423	        if duplicate_store && let Some(counters) = counters {
424	            counters.inc_warning(EventWarningKind::DuplicateStore);
425	        }
426	        Ok(())
427	    }
428	
429	    fn try_reuse_parent_edge(
430	        &mut self,
431	        worker: WorkerWithDpRank,
432	        node: &SharedRadixBlock,
433	        parent_pos: usize,
434	        blocks: &[KvCacheStoredBlockData],
435	    ) -> Option<bool> {
436	        let (reuse_cutoff, append_start) = {
437	            let node_ref = node.borrow();
438	            if node_ref.state.suffix_matches_store(parent_pos, blocks) {
439	                (Some(parent_pos + 1 + blocks.len()), None)
440	            } else if !node_ref.internal {
441	                (
442	                    None,
443	                    node_ref.state.store_starts_with_suffix(parent_pos, blocks),
444	                )
445	            } else {
446	                (None, None)
447	            }
448	        };
449	
450	        if let Some(cutoff) = reuse_cutoff {
451	            let changed = node
452	                .borrow_mut()
453	                .state
454	                .cover_prefix_for_worker(worker, cutoff);
455	            let lookup_changed = self.update_lookup_for_blocks(worker, blocks, node);
456	            return Some(!changed && !lookup_changed);
457	        }
458	
459	        if let Some(append_start) = append_start {
460	            node.borrow_mut()
461	                .state
462	                .append_blocks_to_leaf(worker, &blocks[append_start..]);
463	            self.update_lookup_for_blocks(worker, blocks, node);
464	            return Some(false);
465	        }
466	
467	        None
468	    }
469	
470	    fn split_node(&mut self, node: &SharedRadixBlock, pos: usize) {
471	        let suffix = {
472	            let mut node_ref = node.borrow_mut();
473	            debug_assert!(pos > 0 && pos < node_ref.state.edge.len());
474	
475	            let suffix_edge = node_ref.state.edge.split_off(pos);
476	            let suffix_first_local = suffix_edge[0].0;
477	            for &(_, hash) in &suffix_edge {
478	                node_ref.state.edge_index.remove(&hash);
479	            }
480	
481	            let mut suffix_full = FxHashSet::with_capacity_and_hasher(
482	                node_ref.state.full_edge_workers.len(),
483	                FxBuildHasher,
484	            );
485	            suffix_full.extend(node_ref.state.full_edge_workers.iter().copied());
486	            let mut suffix_cutoffs = FxHashMap::with_capacity_and_hasher(
487	                node_ref.state.worker_cutoffs.len(),
488	                FxBuildHasher,
489	            );
490	            let mut promote_prefix = Vec::new();
491	            for (&worker, &cutoff) in &node_ref.state.worker_cutoffs {
492	                if cutoff < pos {
493	                    continue;
494	                }
495	                promote_prefix.push(worker);
496	                let suffix_cutoff = cutoff - pos;
497	                if suffix_cutoff > 0 {
498	                    suffix_cutoffs.insert(worker, suffix_cutoff);
499	                }
500	            }
501	            for worker in promote_prefix {
502	                node_ref.state.worker_cutoffs.remove(&worker);
503	                node_ref.state.full_edge_workers.insert(worker);
504	            }
505	
506	            let suffix = Rc::new(RefCell::new(RadixBlock {
507	                state: NodeState {
508	                    edge_index: NodeState::edge_index_for(&suffix_edge),
509	                    edge: suffix_edge,
510	                    worker_cutoffs: suffix_cutoffs,
511	                    full_edge_workers: suffix_full,
512	                },
513	                children: std::mem::take(&mut node_ref.children),
514	                internal: node_ref.internal,
515	            }));
516	            node_ref.children.insert(suffix_first_local, suffix.clone());
517	            node_ref.internal = true;
518	            suffix
519	        };
520	
521	        let suffix_ref = suffix.borrow();
522	        for &worker in &suffix_ref.state.full_edge_workers {
523	            let blocks = suffix_ref.state.edge.iter().map(|&(_, hash)| hash);
524	            let lookup = self.lookup.get_mut(&worker).unwrap();
525	            for hash in blocks {
526	                lookup.insert(hash, suffix.clone());
527	            }
528	        }
529	        for (&worker, &cutoff) in &suffix_ref.state.worker_cutoffs {
530	            let lookup = self.lookup.get_mut(&worker).unwrap();
531	            for &(_, hash) in &suffix_ref.state.edge[..cutoff] {
532	                lookup.insert(hash, suffix.clone());
533	            }
534	        }
535	    }
536	
537	    fn update_lookup_for_blocks(
538	        &mut self,
539	        worker: WorkerWithDpRank,
540	        blocks: &[KvCacheStoredBlockData],
541	        node: &SharedRadixBlock,
542	    ) -> bool {
543	        let lookup = self.lookup.get_mut(&worker).unwrap();
544	        let mut changed = false;
545	        for block in blocks {
546	            match lookup.insert(block.block_hash, node.clone()) {
547	                Some(existing) if Rc::ptr_eq(&existing, node) => {}
548	                _ => changed = true,
549	            }
550	        }
551	        changed
552	    }
553	
554	    fn log_missing_parent(
555	        &self,
556	        worker: WorkerWithDpRank,
557	        event_id: u64,
558	        store: &KvCacheStoreData,
559	    ) {
560	        tracing::warn!(
561	            worker_id = worker.worker_id,
562	            dp_rank = worker.dp_rank,
563	            event_id,
564	            parent_hash = ?store.parent_hash,
565	            num_blocks = store.blocks.len(),
566	            "Failed to find parent block; skipping store operation"
567	        );
568	    }
569	
570	    fn apply_removed(
571	        &mut self,
572	        worker: WorkerWithDpRank,
573	        remove: KvCacheRemoveData,
574	        event_id: u64,
575	    ) -> Result<(), KvCacheEventError> {
576	        let Some(lookup) = self.lookup.get_mut(&worker) else {
577	            return Err(KvCacheEventError::BlockNotFound);
578	        };
579	        let mut first_error = None;
580	        let mut eagerly_removed = FxHashSet::default();
581	        let mut block_hashes = remove.block_hashes.into_iter().peekable();
582	
583	        while let Some(block_hash) = block_hashes.next() {
584	            let Some(node) = lookup.remove(&block_hash) else {
585	                if eagerly_removed.contains(&block_hash) {
586	                    continue;
587	                }
588	                tracing::warn!(
589	                    worker_id = worker.worker_id,
590	                    dp_rank = worker.dp_rank,
591	                    event_id,
592	                    ?block_hash,
593	                    "Failed to find block to remove; skipping remove operation"
594	                );
595	                first_error.get_or_insert(KvCacheEventError::BlockNotFound);
596	                continue;
597	            };
598	
599	            let (min_pos, min_hash) = {
600	                let node_ref = node.borrow();
601	                let Some(&first_pos) = node_ref.state.edge_index.get(&block_hash) else {
602	                    drop(node_ref);
603	                    lookup.insert(block_hash, node);
604	                    first_error.get_or_insert(KvCacheEventError::BlockNotFound);
605	                    continue;
606	                };
607	                let mut min_pos = first_pos;
608	                let mut min_hash = block_hash;
609	                if node_ref.state.covers_pos(worker, first_pos) {
610	                    while let Some(&candidate_hash) = block_hashes.peek() {
611	                        let Some(candidate_node) = lookup.get(&candidate_hash) else {
612	                            break;
613	                        };
614	                        if !Rc::ptr_eq(&node, candidate_node) {
615	                            break;
616	                        }
617	                        let Some(&candidate_pos) = node_ref.state.edge_index.get(&candidate_hash)
618	                        else {
619	                            break;
620	                        };
621	                        if !node_ref.state.covers_pos(worker, candidate_pos) {
622	                            break;
623	                        }
624	                        if candidate_pos < min_pos {
625	                            min_pos = candidate_pos;
626	                            min_hash = candidate_hash;
627	                        }
628	                        block_hashes.next();
629	                    }
630	                }
631	                (min_pos, min_hash)
632	            };
633	
634	            let outcome = {
635	                let mut node_ref = node.borrow_mut();
636	                // TODO(CORRECTNESS): Invalidate this worker throughout the descendant
637	                // subtree when a mid-edge removal leaves the node alive for another
638	                // worker. Otherwise stale descendants can be reused as store parents,
639	                // reactivated by restoring only the removed block, or emitted by dumps
640	                // without a valid worker-specific parent.
641	                let outcome = node_ref
642	                    .state
643	                    .remove_worker_at_pos(worker, min_pos, min_hash);
644	                node_ref.clear_children_if_unreachable();
645	                outcome
646	            };
647	            for stale_hash in outcome.stale_hashes {
648	                lookup.remove(&stale_hash);
649	                eagerly_removed.insert(stale_hash);
650	            }
651	        }
652	
653	        first_error.map_or(Ok(()), Err)
654	    }
655	
656	    fn remove_or_clear_worker_blocks(&mut self, worker_id: WorkerId, keep_worker: bool) {
657	        let workers = self
658	            .lookup
659	            .keys()
660	            .filter(|worker| worker.worker_id == worker_id)
661	            .copied()
662	            .collect::<Vec<_>>();
663	
664	        for worker in workers {
665	            let Some((worker_key, blocks)) = self.lookup.remove_entry(&worker) else {
666	                continue;
667	            };
668	            let mut seen = FxHashSet::default();
669	            for node in blocks.into_values() {
670	                if !seen.insert(Rc::as_ptr(&node)) {
671	                    continue;
672	                }
673	                let mut node_ref = node.borrow_mut();
674	                node_ref.state.drop_worker(worker);
675	                node_ref.clear_children_if_unreachable();
676	            }
677	            if keep_worker {
678	                self.lookup.insert(worker_key, FxHashMap::default());
679	            }
680	        }
681	    }
682	
683	    pub fn remove_worker(&mut self, worker_id: WorkerId) {
684	        self.remove_or_clear_worker_blocks(worker_id, false);
685	    }
