687	    pub fn remove_worker_dp_rank(&mut self, worker_id: WorkerId, dp_rank: DpRank) {
688	        let worker = WorkerWithDpRank { worker_id, dp_rank };
689	        let Some(blocks) = self.lookup.remove(&worker) else {
690	            return;
691	        };
692	        let mut seen = FxHashSet::default();
693	        for node in blocks.into_values() {
694	            if !seen.insert(Rc::as_ptr(&node)) {
695	                continue;
696	            }
697	            let mut node_ref = node.borrow_mut();
698	            node_ref.state.drop_worker(worker);
699	            node_ref.clear_children_if_unreachable();
700	        }
701	    }
