707	    pub fn get_workers(&self) -> Vec<WorkerId> {
708	        let mut workers = self
709	            .lookup
710	            .keys()
711	            .map(|worker| worker.worker_id)
712	            .collect::<Vec<_>>();
713	        workers.sort_unstable();
714	        workers.dedup();
715	        workers
716	    }
