718	    pub fn dump_tree_as_events(&self) -> Vec<RouterEvent> {
719	        let mut events = Vec::new();
720	        let mut event_id = 0u64;
721	        let mut queue = self
722	            .root
723	            .borrow()
724	            .children
725	            .values()
726	            .cloned()
727	            .map(|node| (node, None))
728	            .collect::<VecDeque<_>>();
729	
730	        while let Some((start_node, parent_hash)) = queue.pop_front() {
731	            let mut merged_edge = Vec::new();
732	            let mut current = start_node;
733	
734	            loop {
735	                let (full_workers, cutoffs, live_children, can_merge) = {
736	                    let node = current.borrow();
737	                    if !node.state.has_any_workers() && node.children.is_empty() {
738	                        break;
739	                    }
740	                    merged_edge.extend_from_slice(&node.state.edge);
741	                    let live_children = node
742	                        .children
743	                        .values()
744	                        .filter(|child| {
745	                            let child = child.borrow();
746	                            child.state.has_any_workers() || !child.children.is_empty()
747	                        })
748	                        .cloned()
749	                        .collect::<Vec<_>>();
750	                    let can_merge =
751	                        node.state.worker_cutoffs.is_empty() && live_children.len() == 1 && {
752	                            let child = live_children[0].borrow();
753	                            child.state.worker_cutoffs.is_empty()
754	                                && child.state.full_edge_workers == node.state.full_edge_workers
755	                                && child.state.has_any_workers()
756	                        };
757	                    (
758	                        node.state
759	                            .full_edge_workers
760	                            .iter()
761	                            .copied()
762	                            .collect::<Vec<_>>(),
763	                        node.state
764	                            .worker_cutoffs
765	                            .iter()
766	                            .map(|(&worker, &cutoff)| (worker, cutoff))
767	                            .collect::<Vec<_>>(),
768	                        live_children,
769	                        can_merge,
770	                    )
771	                };
772	
773	                if can_merge {
774	                    current = live_children[0].clone();
775	                    continue;
776	                }
777	                if merged_edge.is_empty() {
778	                    break;
779	                }
780	
781	                let last_hash = merged_edge.last().unwrap().1;
782	
783	                append_dump_events(
784	                    &mut events,
785	                    &mut event_id,
786	                    parent_hash,
787	                    &merged_edge,
788	                    &full_workers,
789	                    &cutoffs,
790	                );
791	                for child in live_children {
792	                    queue.push_back((child, Some(last_hash)));
793	                }
794	                break;
795	            }
796	        }
797	
798	        events
799	    }
800	
801	    pub fn current_size(&self) -> usize {
802	        self.lookup.values().map(FxHashMap::len).sum()
803	    }
