456	struct RankLruState {
457	    capacity: usize,
458	    release_epoch: u64,
459	    next_copy_id: BlockCopyId,
460	    copies: FxHashMap<BlockCopyId, BlockCopy>,
461	    by_hash: FxHashMap<SequenceHash, Vec<BlockCopyId>>,
462	    inactive: BTreeSet<InactiveKey>,
463	    leases: FxHashMap<ApproximateLruRequestId, LeaseState>,
464	    private_blocks: usize,
465	    evicted_blocks: u64,
466	}
467	
468	impl RankLruState {
469	    fn new(capacity: usize) -> Self {
470	        Self {
471	            capacity,
472	            release_epoch: 0,
473	            next_copy_id: 1,
474	            copies: FxHashMap::default(),
475	            by_hash: FxHashMap::default(),
476	            inactive: BTreeSet::new(),
477	            leases: FxHashMap::default(),
478	            private_blocks: 0,
479	            evicted_blocks: 0,
480	        }
481	    }
482	
483	    fn next_release_epoch(&mut self) -> u64 {
484	        self.release_epoch = self.release_epoch.wrapping_add(1).max(1);
485	        self.release_epoch
486	    }
487	
488	    fn inactive_key(copy_id: BlockCopyId, copy: &BlockCopy) -> InactiveKey {
489	        InactiveKey {
490	            release_epoch: copy.release_epoch,
491	            reverse_position: Reverse(copy.sequence_position),
492	            copy_id,
493	        }
494	    }
495	
496	    fn acquire(
497	        &mut self,
498	        lru_request_id: ApproximateLruRequestId,
499	        blocks: &[ApproximateLruBlock],
500	        private_blocks: usize,
501	    ) -> Result<Vec<SequenceHash>, KvRouterError> {
502	        if self.leases.contains_key(&lru_request_id) {
503	            return Err(KvRouterError::Unsupported(format!(
504	                "duplicate approximate LRU request {lru_request_id}"
505	            )));
506	        }
507	
508	        let mut lease = LeaseState {
509	            copies: Vec::with_capacity(blocks.len()),
510	            private_blocks,
511	        };
512	        let mut prefix_hit = true;
513	
514	        for (position, block) in blocks.iter().enumerate() {
515	            let copy_id = if prefix_hit {
516	                self.by_hash
517	                    .get(&block.sequence_hash)
518	                    .and_then(|copies| copies.first())
519	                    .copied()
520	            } else {
521	                None
522	            };
523	
524	            let copy_id = if let Some(copy_id) = copy_id {
525	                let copy = self
526	                    .copies
527	                    .get_mut(&copy_id)
528	                    .ok_or(KvRouterError::IndexerDroppedRequest)?;
529	                if copy.refs == 0 {
530	                    let key = Self::inactive_key(copy_id, copy);
531	                    self.inactive.remove(&key);
532	                }
533	                copy.refs += 1;
534	                copy.sequence_position = position;
535	                copy_id
536	            } else {
537	                prefix_hit = false;
538	                let copy_id = self.next_copy_id;
539	                self.next_copy_id = self.next_copy_id.wrapping_add(1).max(1);
540	                self.copies.insert(
541	                    copy_id,
542	                    BlockCopy {
543	                        sequence_hash: block.sequence_hash,
544	                        refs: 1,
545	                        release_epoch: 0,
546	                        sequence_position: position,
547	                    },
548	                );
549	                self.by_hash
550	                    .entry(block.sequence_hash)
551	                    .or_default()
552	                    .push(copy_id);
553	                copy_id
554	            };
555	            lease.copies.push(copy_id);
556	        }
557	
558	        self.private_blocks += private_blocks;
559	        self.leases.insert(lru_request_id, lease);
560	        Ok(self.reconcile())
561	    }
562	
563	    fn materialize(
564	        &mut self,
565	        lru_request_id: ApproximateLruRequestId,
566	        blocks: &[ApproximateLruBlock],
567	        start_position: usize,
568	        private_blocks: usize,
569	    ) -> Option<Vec<SequenceHash>> {
570	        let mut lease = self.leases.remove(&lru_request_id)?;
571	        for (offset, block) in blocks.iter().enumerate() {
572	            let copy_id = self.next_copy_id;
573	            self.next_copy_id = self.next_copy_id.wrapping_add(1).max(1);
574	            self.copies.insert(
575	                copy_id,
576	                BlockCopy {
577	                    sequence_hash: block.sequence_hash,
578	                    refs: 1,
579	                    release_epoch: 0,
580	                    sequence_position: start_position + offset,
581	                },
582	            );
583	            self.by_hash
584	                .entry(block.sequence_hash)
585	                .or_default()
586	                .push(copy_id);
587	            lease.copies.push(copy_id);
588	        }
589	        if private_blocks > lease.private_blocks {
590	            self.private_blocks += private_blocks - lease.private_blocks;
591	        } else {
592	            self.private_blocks -= lease.private_blocks - private_blocks;
593	        }
594	        lease.private_blocks = private_blocks;
595	        self.leases.insert(lru_request_id, lease);
596	        Some(self.reconcile())
597	    }
598	
599	    fn release(&mut self, lru_request_id: ApproximateLruRequestId) -> Vec<SequenceHash> {
600	        let Some(lease) = self.leases.remove(&lru_request_id) else {
601	            return Vec::new();
602	        };
603	        let release_epoch = self.next_release_epoch();
604	        self.private_blocks = self.private_blocks.saturating_sub(lease.private_blocks);
605	        for copy_id in lease.copies {
606	            let Some(copy) = self.copies.get_mut(&copy_id) else {
607	                continue;
608	            };
609	            if copy.refs == 0 {
610	                continue;
611	            }
612	            copy.refs -= 1;
613	            if copy.refs == 0 {
614	                copy.release_epoch = release_epoch;
615	                self.inactive.insert(Self::inactive_key(copy_id, copy));
616	            }
617	        }
618	        self.reconcile()
619	    }
620	
621	    fn reconcile(&mut self) -> Vec<SequenceHash> {
622	        let mut removed_hashes = Vec::new();
623	        let mut evicted_blocks = 0_u64;
624	        while self.resident_blocks() > self.capacity {
625	            let Some(key) = self.inactive.pop_first() else {
626	                break;
627	            };
628	            let Some(copy) = self.copies.remove(&key.copy_id) else {
629	                continue;
630	            };
631	            evicted_blocks = evicted_blocks.saturating_add(1);
632	            debug_assert_eq!(copy.refs, 0);
633	            let mut remove_hash = false;
634	            if let Some(copies) = self.by_hash.get_mut(&copy.sequence_hash) {
635	                if let Some(position) = copies.iter().position(|id| *id == key.copy_id) {
636	                    copies.swap_remove(position);
637	                }
638	                remove_hash = copies.is_empty();
639	            }
640	            if remove_hash {
641	                self.by_hash.remove(&copy.sequence_hash);
642	                removed_hashes.push(copy.sequence_hash);
643	            }
644	        }
645	        self.evicted_blocks = self.evicted_blocks.saturating_add(evicted_blocks);
646	        removed_hashes
647	    }
648	
649	    fn resident_blocks(&self) -> usize {
650	        self.copies.len() + self.private_blocks
651	    }
652	
653	    fn active_blocks(&self) -> usize {
654	        self.copies.values().filter(|copy| copy.refs > 0).count() + self.private_blocks
655	    }
656	
657	    fn stats(&self) -> ApproximateLruStats {
658	        ApproximateLruStats {
659	            ranks: 1,
660	            fallback_ranks: 0,
661	            resident_blocks: self.resident_blocks(),
662	            active_blocks: self.active_blocks(),
663	            inactive_blocks: self.inactive.len(),
664	            private_blocks: self.private_blocks,
665	            leases: self.leases.len(),
666	            overcapacity_blocks: self.resident_blocks().saturating_sub(self.capacity),
667	            ..Default::default()
668	        }
669	    }
670	
671	    #[cfg(test)]
672	    fn assert_invariants(&self) {
673	        assert_eq!(
674	            self.inactive.len(),
675	            self.copies.values().filter(|copy| copy.refs == 0).count()
676	        );
677	        assert_eq!(
678	            self.private_blocks,
679	            self.leases
680	                .values()
681	                .map(|lease| lease.private_blocks)
682	                .sum::<usize>()
683	        );
684	        for (copy_id, copy) in &self.copies {
685	            assert!(
686	                self.by_hash
687	                    .get(&copy.sequence_hash)
688	                    .is_some_and(|copies| copies.contains(copy_id))
689	            );
690	            let inactive_key = Self::inactive_key(*copy_id, copy);
691	            assert_eq!(copy.refs == 0, self.inactive.contains(&inactive_key));
692	        }
693	        for (hash, copy_ids) in &self.by_hash {
694	            assert!(!copy_ids.is_empty());
695	            for copy_id in copy_ids {
696	                assert_eq!(
697	                    self.copies.get(copy_id).map(|copy| copy.sequence_hash),
698	                    Some(*hash)
699	                );
700	            }
701	        }
702	        for lease in self.leases.values() {
703	            for copy_id in &lease.copies {
704	                assert!(self.copies.contains_key(copy_id));
705	            }
706	        }
707	    }
708	}
