783	    pub fn apply(
784	        &mut self,
785	        command: ApproximateLruCommand,
786	    ) -> Result<ApproximateLruApplyOutput, KvRouterError> {
787	        let mut events = Vec::new();
788	        let mut ttl_update = None;
789	        let reply = match command {
790	            ApproximateLruCommand::SetCapacity {
791	                worker,
792	                incarnation,
793	                capacity,
794	            } => {
795	                if self
796	                    .ranks
797	                    .get(&worker)
798	                    .is_some_and(|state| state.incarnation() != incarnation)
799	                {
800	                    self.push_clear_event(&mut events, worker);
801	                    self.ranks.remove(&worker);
802	                    ttl_update = Some(ApproximateTtlUpdate::Reset(worker));
803	                }
804	                if let Some(capacity) = capacity.filter(|capacity| *capacity > 0) {
805	                    let (removed, evicted) = match self.ranks.get_mut(&worker) {
806	                        Some(WorkerRetentionState::Lru { state, .. }) => {
807	                            let before = state.evicted_blocks;
808	                            state.capacity = capacity;
809	                            let removed = state.reconcile();
810	                            (removed, state.evicted_blocks.saturating_sub(before))
811	                        }
812	                        Some(WorkerRetentionState::TtlFallback { .. }) => (Vec::new(), 0),
813	                        None => {
814	                            self.ranks.insert(
815	                                worker,
816	                                WorkerRetentionState::Lru {
817	                                    incarnation,
818	                                    state: RankLruState::new(capacity),
819	                                },
820	                            );
821	                            (Vec::new(), 0)
822	                        }
823	                    };
824	                    self.record_evictions(evicted);
825	                    self.push_remove_event(&mut events, worker, removed);
826	                } else {
827	                    let was_lru = matches!(
828	                        self.ranks.get(&worker),
829	                        Some(WorkerRetentionState::Lru { .. })
830	                    );
831	                    let was_fallback = matches!(
832	                        self.ranks.get(&worker),
833	                        Some(WorkerRetentionState::TtlFallback { .. })
834	                    );
835	                    if was_lru {
836	                        self.push_clear_event(&mut events, worker);
837	                    }
838	                    if !was_fallback {
839	                        self.fallback_activations = self.fallback_activations.saturating_add(1);
840	                    }
841	                    self.ranks
842	                        .insert(worker, WorkerRetentionState::TtlFallback { incarnation });
843	                }
844	                ApproximateLruReply::Applied
845	            }
846	            ApproximateLruCommand::ResetRank { worker } => {
847	                self.ranks.remove(&worker);
848	                self.push_clear_event(&mut events, worker);
849	                ttl_update = Some(ApproximateTtlUpdate::Reset(worker));
850	                ApproximateLruReply::Applied
851	            }
852	            ApproximateLruCommand::Acquire {
853	                worker,
854	                incarnation,
855	                lru_request_id,
856	                blocks,
857	                private_blocks,
858	            } => {
859	                self.requests = self.requests.saturating_add(1);
860	                self.request_messages = self.request_messages.saturating_add(1);
861	                let Some(state) = self.ranks.get(&worker) else {
862	                    return Ok(ApproximateLruApplyOutput {
863	                        events,
864	                        reply: ApproximateLruReply::Acquired(ApproximateAcquireMode::Ignored),
865	                        ttl_update,
866	                    });
867	                };
868	                if state.incarnation() != incarnation {
869	                    return Ok(ApproximateLruApplyOutput {
870	                        events,
871	                        reply: ApproximateLruReply::Acquired(ApproximateAcquireMode::Ignored),
872	                        ttl_update,
873	                    });
874	                }
875	                if matches!(state, WorkerRetentionState::TtlFallback { .. }) {
876	                    let entries = blocks
877	                        .iter()
878	                        .enumerate()
879	                        .map(|(seq_position, block)| BlockEntry {
880	                            key: ExternalSequenceBlockHash(block.sequence_hash),
881	                            worker,
882	                            seq_position,
883	                        })
884	                        .collect();
885	                    self.push_store_event(&mut events, worker, None, blocks);
886	                    return Ok(ApproximateLruApplyOutput {
887	                        events,
888	                        reply: ApproximateLruReply::Acquired(ApproximateAcquireMode::TtlFallback),
889	                        ttl_update: Some(ApproximateTtlUpdate::Refresh(entries)),
890	                    });
891	                }
892	                let Some(WorkerRetentionState::Lru { state, .. }) = self.ranks.get_mut(&worker)
893	                else {
894	                    unreachable!("retention state was checked above");
895	                };
896	                let before = state.evicted_blocks;
897	                let removed = state.acquire(lru_request_id, &blocks, private_blocks)?;
898	                let evicted = state.evicted_blocks.saturating_sub(before);
899	                self.record_evictions(evicted);
900	                self.push_store_event(&mut events, worker, None, blocks);
901	                self.push_remove_event(&mut events, worker, removed);
902	                ApproximateLruReply::Acquired(ApproximateAcquireMode::Lru)
903	            }
904	            ApproximateLruCommand::Materialize {
905	                worker,
906	                incarnation,
907	                lru_request_id,
908	                parent_hash,
909	                blocks,
910	                start_position,
911	                private_blocks,
912	            } => {
913	                self.request_messages = self.request_messages.saturating_add(1);
914	                if !blocks.is_empty() {
915	                    self.output_batches = self.output_batches.saturating_add(1);
916	                }
917	                if let Some(WorkerRetentionState::Lru {
918	                    incarnation: current,
919	                    state,
920	                }) = self.ranks.get_mut(&worker)
921	                    && *current == incarnation
922	                {
923	                    let before = state.evicted_blocks;
924	                    if let Some(removed) =
925	                        state.materialize(lru_request_id, &blocks, start_position, private_blocks)
926	                    {
927	                        let evicted = state.evicted_blocks.saturating_sub(before);
928	                        self.record_evictions(evicted);
929	                        self.push_store_event(&mut events, worker, parent_hash, blocks);
930	                        self.push_remove_event(&mut events, worker, removed);
931	                    }
932	                }
933	                ApproximateLruReply::Applied
934	            }
935	            ApproximateLruCommand::Release {
936	                worker,
937	                incarnation,
938	                lru_request_id,
939	            } => {
940	                self.request_messages = self.request_messages.saturating_add(1);
941	                if let Some(WorkerRetentionState::Lru {
942	                    incarnation: current,
943	                    state,
944	                }) = self.ranks.get_mut(&worker)
945	                    && *current == incarnation
946	                {
947	                    let before = state.evicted_blocks;
948	                    let removed = state.release(lru_request_id);
949	                    let evicted = state.evicted_blocks.saturating_sub(before);
950	                    self.record_evictions(evicted);
951	                    self.push_remove_event(&mut events, worker, removed);
952	                }
953	                ApproximateLruReply::Applied
954	            }
955	            ApproximateLruCommand::Stats => ApproximateLruReply::Stats(self.stats()),
956	        };
957	        Ok(ApproximateLruApplyOutput {
958	            events,
959	            reply,
960	            ttl_update,
961	        })
962	    }
963	
964	    fn next_event_id(&mut self) -> u64 {
965	        self.next_event_id = self.next_event_id.wrapping_add(1).max(1);
966	        self.next_event_id
967	    }
