969	    fn record_evictions(&mut self, evicted: u64) {
970	        if evicted == 0 {
971	            return;
972	        }
973	        self.eviction_batches = self.eviction_batches.saturating_add(1);
974	        self.evicted_blocks = self.evicted_blocks.saturating_add(evicted);
975	    }
