977	    fn push_store_event(
978	        &mut self,
979	        events: &mut Vec<RouterEvent>,
980	        worker: WorkerWithDpRank,
981	        parent_hash: Option<SequenceHash>,
982	        blocks: Vec<ApproximateLruBlock>,
983	    ) {
984	        if blocks.is_empty() {
985	            return;
986	        }
987	        let stored = blocks
988	            .into_iter()
989	            .map(|block| KvCacheStoredBlockData {
990	                tokens_hash: block.local_hash,
991	                block_hash: ExternalSequenceBlockHash(block.sequence_hash),
992	                mm_extra_info: None,
993	            })
994	            .collect();
995	        events.push(RouterEvent::new(
996	            worker.worker_id,
997	            KvCacheEvent {
998	                event_id: self.next_event_id(),
999	                data: KvCacheEventData::Stored(KvCacheStoreData {
1000	                    parent_hash: parent_hash.map(ExternalSequenceBlockHash),
1001	                    start_position: None,
1002	                    blocks: stored,
1003	                }),
1004	                dp_rank: worker.dp_rank,
1005	            },
1006	        ));
1007	    }
1008	
1009	    fn push_remove_event(
1010	        &mut self,
1011	        events: &mut Vec<RouterEvent>,
1012	        worker: WorkerWithDpRank,
1013	        hashes: Vec<SequenceHash>,
1014	    ) {
1015	        if hashes.is_empty() {
1016	            return;
1017	        }
1018	        events.push(RouterEvent::new(
1019	            worker.worker_id,
1020	            KvCacheEvent {
1021	                event_id: self.next_event_id(),
1022	                data: KvCacheEventData::Removed(KvCacheRemoveData {
1023	                    block_hashes: hashes.into_iter().map(ExternalSequenceBlockHash).collect(),
1024	                }),
1025	                dp_rank: worker.dp_rank,
1026	            },
1027	        ));
1028	    }
1029	
1030	    fn push_clear_event(&mut self, events: &mut Vec<RouterEvent>, worker: WorkerWithDpRank) {
1031	        events.push(RouterEvent::new(
1032	            worker.worker_id,
1033	            KvCacheEvent {
1034	                event_id: self.next_event_id(),
1035	                data: KvCacheEventData::Cleared,
1036	                dp_rank: worker.dp_rank,
1037	            },
1038	        ));
1039	    }
