1041	    fn stats(&self) -> ApproximateLruStats {
1042	        let mut total = ApproximateLruStats::default();
1043	        for state in self.ranks.values() {
1044	            match state {
1045	                WorkerRetentionState::Lru { state, .. } => {
1046	                    let stats = state.stats();
1047	                    total.ranks += 1;
1048	                    total.resident_blocks += stats.resident_blocks;
1049	                    total.active_blocks += stats.active_blocks;
1050	                    total.inactive_blocks += stats.inactive_blocks;
1051	                    total.private_blocks += stats.private_blocks;
1052	                    total.leases += stats.leases;
1053	                    total.overcapacity_blocks += stats.overcapacity_blocks;
1054	                }
1055	                WorkerRetentionState::TtlFallback { .. } => {
1056	                    total.fallback_ranks += 1;
1057	                }
1058	            }
1059	        }
1060	        total.requests = self.requests;
1061	        total.request_messages = self.request_messages;
1062	        total.output_batches = self.output_batches;
1063	        total.fallback_activations = self.fallback_activations;
1064	        total.eviction_batches = self.eviction_batches;
1065	        total.evicted_blocks = self.evicted_blocks;
1066	        total.mutation_queue_depth = self.mutation_queue_depth;
1067	        total.mutation_wait_ns = self.mutation_wait_ns;
1068	        total.mutation_wait_samples = self.mutation_wait_samples;
1069	        total
1070	    }
1071	}
