                Some(existing) => {
                    {
                        let existing_guard = existing.read();
                        if existing_guard.block_hash != Some(block_data.block_hash) {
                            duplicate_store = false;
                            tracing::warn!(
                                expected = ?block_data.block_hash,
                                actual = ?existing_guard.block_hash,
